-- Schema drift closure, tables batch 15: content, events and traceability
-- (content entries, events, event reservations, product batches, batch events,
-- product certifications, batch-certification links).
--
-- This completes the table half of the drift closure: every table present in
-- the live public and private schemas now has a CREATE TABLE definition in
-- supabase/migrations.
--
-- DDL generated by the database from its own catalogs via
-- scripts/generate-schema-ddl.sql, then md5-verified against that generated
-- text. Checked for constraint triggers: none in this batch. Foreign keys are
-- emitted after all CREATE TABLE statements so the file is order-independent.
--
-- Applying is a no-op against the live project.

CREATE TABLE IF NOT EXISTS public.content_entries (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  legacy_source text,
  legacy_id text,
  content_type text NOT NULL,
  slug text NOT NULL,
  title text NOT NULL,
  summary text NOT NULL DEFAULT ''::text,
  body_markdown text NOT NULL DEFAULT ''::text,
  body_html_sanitized text NOT NULL DEFAULT ''::text,
  hero_image_path text,
  author_user_id uuid,
  related_product_id uuid,
  related_producer_id uuid,
  status text NOT NULL DEFAULT 'draft'::text,
  locale text NOT NULL DEFAULT 'tr'::text,
  translation_group_id uuid,
  tags text[] NOT NULL DEFAULT '{}'::text[],
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  seo jsonb NOT NULL DEFAULT '{}'::jsonb,
  scheduled_at timestamp with time zone,
  published_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  deleted_at timestamp with time zone,
  CONSTRAINT content_entries_content_type_slug_locale_key UNIQUE (content_type, slug, locale),
  CONSTRAINT content_entries_legacy_source_legacy_id_key UNIQUE (legacy_source, legacy_id),
  CONSTRAINT content_entries_pkey PRIMARY KEY (id),
  CONSTRAINT content_entries_check CHECK ((((status = 'published'::text) AND (published_at IS NOT NULL)) OR (status <> 'published'::text))),
  CONSTRAINT content_entries_check1 CHECK ((((status = 'scheduled'::text) AND (scheduled_at IS NOT NULL)) OR (status <> 'scheduled'::text))),
  CONSTRAINT content_entries_content_type_check CHECK ((content_type = ANY (ARRAY['page'::text, 'blog'::text, 'recipe'::text, 'health_guide'::text, 'product_health'::text, 'producer_story'::text, 'faq'::text, 'legal'::text, 'announcement'::text]))),
  CONSTRAINT content_entries_hero_image_path_not_absolute_url CHECK (((hero_image_path IS NULL) OR (hero_image_path !~* '^[a-z][a-z0-9+.-]*:'::text))),
  CONSTRAINT content_entries_locale_check CHECK ((locale = ANY (ARRAY['tr'::text, 'en'::text, 'de'::text, 'fr'::text, 'ku'::text, 'ar'::text]))),
  CONSTRAINT content_entries_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  CONSTRAINT content_entries_seo_check CHECK ((jsonb_typeof(seo) = 'object'::text)),
  CONSTRAINT content_entries_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'scheduled'::text, 'published'::text, 'archived'::text])))
);
ALTER TABLE public.content_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.content_entries FORCE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.event_reservations (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  event_id uuid NOT NULL,
  user_id uuid,
  reservation_code text NOT NULL,
  guest_name text NOT NULL,
  guest_email text NOT NULL,
  guest_phone text NOT NULL,
  guest_count integer NOT NULL,
  notes text,
  status text NOT NULL DEFAULT 'pending'::text,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT event_reservations_reservation_code_key UNIQUE (reservation_code),
  CONSTRAINT event_reservations_pkey PRIMARY KEY (id),
  CONSTRAINT event_reservations_guest_count_check CHECK (((guest_count >= 1) AND (guest_count <= 20))),
  CONSTRAINT event_reservations_status_check CHECK ((status = ANY (ARRAY['pending_payment'::text, 'pending'::text, 'confirmed'::text, 'waitlisted'::text, 'cancelled'::text, 'attended'::text, 'no_show'::text])))
);
ALTER TABLE public.event_reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.event_reservations FORCE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.events (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  legacy_source text,
  legacy_id text,
  slug text NOT NULL,
  title text NOT NULL,
  description text NOT NULL,
  image_path text,
  location_name text NOT NULL,
  location_details jsonb NOT NULL DEFAULT '{}'::jsonb,
  starts_at timestamp with time zone NOT NULL,
  ends_at timestamp with time zone NOT NULL,
  capacity integer,
  reservation_deadline timestamp with time zone,
  status text NOT NULL DEFAULT 'draft'::text,
  translations jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  producer_id uuid,
  event_submission_id uuid,
  ticket_price_minor bigint NOT NULL DEFAULT 0,
  currency text NOT NULL DEFAULT 'TRY'::text,
  platform_commission_basis_points integer NOT NULL DEFAULT 0,
  sale_mode text NOT NULL DEFAULT 'reservation'::text,
  CONSTRAINT events_event_submission_id_key UNIQUE (event_submission_id),
  CONSTRAINT events_legacy_source_legacy_id_key UNIQUE (legacy_source, legacy_id),
  CONSTRAINT events_slug_key UNIQUE (slug),
  CONSTRAINT events_pkey PRIMARY KEY (id),
  CONSTRAINT events_capacity_check CHECK (((capacity IS NULL) OR (capacity > 0))),
  CONSTRAINT events_check CHECK ((ends_at > starts_at)),
  CONSTRAINT events_check1 CHECK (((reservation_deadline IS NULL) OR (reservation_deadline <= starts_at))),
  CONSTRAINT events_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT events_image_path_not_absolute_url CHECK (((image_path IS NULL) OR (image_path !~* '^[a-z][a-z0-9+.-]*:'::text))),
  CONSTRAINT events_location_details_check CHECK ((jsonb_typeof(location_details) = 'object'::text)),
  CONSTRAINT events_platform_commission_check CHECK (((platform_commission_basis_points >= 0) AND (platform_commission_basis_points <= 10000))),
  CONSTRAINT events_sale_mode_check CHECK ((sale_mode = ANY (ARRAY['reservation'::text, 'ticketed'::text]))),
  CONSTRAINT events_sale_mode_price_consistency_check CHECK ((((sale_mode = 'reservation'::text) AND (ticket_price_minor = 0)) OR ((sale_mode = 'ticketed'::text) AND (ticket_price_minor > 0)))),
  CONSTRAINT events_slug_check CHECK ((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text)),
  CONSTRAINT events_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'sold_out'::text, 'cancelled'::text, 'completed'::text]))),
  CONSTRAINT events_ticket_price_minor_check CHECK ((ticket_price_minor >= 0)),
  CONSTRAINT events_translations_check CHECK ((jsonb_typeof(translations) = 'object'::text))
);
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.events FORCE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.product_batch_certifications (
  batch_id uuid NOT NULL,
  certification_id uuid NOT NULL,
  linked_by uuid NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT product_batch_certifications_pkey PRIMARY KEY (batch_id, certification_id)
);
ALTER TABLE public.product_batch_certifications ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.product_batch_events (
  id bigint GENERATED ALWAYS AS IDENTITY,
  batch_id uuid NOT NULL,
  event_type text NOT NULL,
  event_at timestamp with time zone NOT NULL,
  location_label text,
  public_note text NOT NULL DEFAULT ''::text,
  visibility text NOT NULL DEFAULT 'public'::text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  actor_user_id uuid,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT product_batch_events_pkey PRIMARY KEY (id),
  CONSTRAINT product_batch_events_public_note_length_check CHECK ((char_length(public_note) <= 1500)),
  CONSTRAINT product_batch_events_type_check CHECK ((event_type = ANY (ARRAY['harvested'::text, 'produced'::text, 'packed'::text, 'quality_checked'::text, 'stored'::text, 'released'::text, 'recalled'::text, 'correction'::text]))),
  CONSTRAINT product_batch_events_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'private'::text])))
);
ALTER TABLE public.product_batch_events ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.product_batches (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  trace_code text NOT NULL,
  batch_code text NOT NULL,
  product_id uuid NOT NULL,
  variant_id uuid,
  producer_id uuid NOT NULL,
  harvest_date date,
  production_date date,
  packaging_date date,
  best_before_date date,
  origin_country_code text NOT NULL DEFAULT 'TR'::text,
  origin_province text NOT NULL,
  origin_district text NOT NULL,
  origin_village text NOT NULL,
  origin_latitude numeric(9,6),
  origin_longitude numeric(9,6),
  production_method text NOT NULL DEFAULT ''::text,
  initial_quantity numeric(14,3),
  quantity_unit text,
  public_notes text NOT NULL DEFAULT ''::text,
  status text NOT NULL DEFAULT 'draft'::text,
  review_reason text,
  created_by uuid NOT NULL,
  reviewed_by uuid,
  submitted_at timestamp with time zone,
  reviewed_at timestamp with time zone,
  released_at timestamp with time zone,
  recalled_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT product_batches_batch_code_key UNIQUE (batch_code),
  CONSTRAINT product_batches_trace_code_key UNIQUE (trace_code),
  CONSTRAINT product_batches_pkey PRIMARY KEY (id),
  CONSTRAINT product_batches_batch_code_format_check CHECK ((batch_code ~ '^[A-Z0-9._/-]{3,80}$'::text)),
  CONSTRAINT product_batches_coordinates_pair_check CHECK (((origin_latitude IS NULL) = (origin_longitude IS NULL))),
  CONSTRAINT product_batches_country_code_check CHECK ((origin_country_code ~ '^[A-Z]{2}$'::text)),
  CONSTRAINT product_batches_date_order_check CHECK ((((packaging_date IS NULL) OR (harvest_date IS NULL) OR (packaging_date >= harvest_date)) AND ((packaging_date IS NULL) OR (production_date IS NULL) OR (packaging_date >= production_date)) AND ((best_before_date IS NULL) OR (packaging_date IS NULL) OR (best_before_date >= packaging_date)) AND ((best_before_date IS NULL) OR (packaging_date IS NOT NULL) OR (production_date IS NULL) OR (best_before_date >= production_date)) AND ((best_before_date IS NULL) OR (packaging_date IS NOT NULL) OR (production_date IS NOT NULL) OR (harvest_date IS NULL) OR (best_before_date >= harvest_date)))),
  CONSTRAINT product_batches_latitude_check CHECK (((origin_latitude IS NULL) OR ((origin_latitude >= ('-90'::integer)::numeric) AND (origin_latitude <= (90)::numeric)))),
  CONSTRAINT product_batches_longitude_check CHECK (((origin_longitude IS NULL) OR ((origin_longitude >= ('-180'::integer)::numeric) AND (origin_longitude <= (180)::numeric)))),
  CONSTRAINT product_batches_quantity_check CHECK (((initial_quantity IS NULL) OR (initial_quantity > (0)::numeric))),
  CONSTRAINT product_batches_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'released'::text, 'rejected'::text, 'recalled'::text, 'archived'::text]))),
  CONSTRAINT product_batches_trace_code_format_check CHECK ((trace_code ~ '^GO-TRC-[A-Z0-9]{10,24}$'::text))
);
ALTER TABLE public.product_batches ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.product_certifications (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL,
  certificate_type text NOT NULL,
  issuer text NOT NULL,
  certificate_number text,
  issued_at date,
  expires_at date,
  verification_url text,
  status text NOT NULL DEFAULT 'valid'::text,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT product_certifications_pkey PRIMARY KEY (id),
  CONSTRAINT product_certifications_check CHECK (((expires_at IS NULL) OR (issued_at IS NULL) OR (expires_at >= issued_at))),
  CONSTRAINT product_certifications_no_external_verification_url CHECK ((verification_url IS NULL)),
  CONSTRAINT product_certifications_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'valid'::text, 'expired'::text, 'revoked'::text])))
);
ALTER TABLE public.product_certifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_certifications FORCE ROW LEVEL SECURITY;

-- foreign keys (added after all tables exist)

ALTER TABLE public.content_entries ADD CONSTRAINT content_entries_author_user_id_fkey FOREIGN KEY (author_user_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public.content_entries ADD CONSTRAINT content_entries_related_producer_id_fkey FOREIGN KEY (related_producer_id) REFERENCES producers(id) ON DELETE SET NULL;
ALTER TABLE public.content_entries ADD CONSTRAINT content_entries_related_product_id_fkey FOREIGN KEY (related_product_id) REFERENCES products(id) ON DELETE SET NULL;
ALTER TABLE public.event_reservations ADD CONSTRAINT event_reservations_event_id_fkey FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE RESTRICT;
ALTER TABLE public.event_reservations ADD CONSTRAINT event_reservations_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public.events ADD CONSTRAINT events_event_submission_id_fkey FOREIGN KEY (event_submission_id) REFERENCES private.producer_event_submissions(id) ON DELETE SET NULL;
ALTER TABLE public.events ADD CONSTRAINT events_producer_id_fkey FOREIGN KEY (producer_id) REFERENCES producers(id) ON DELETE SET NULL;
ALTER TABLE public.product_batch_certifications ADD CONSTRAINT product_batch_certifications_batch_id_fkey FOREIGN KEY (batch_id) REFERENCES product_batches(id) ON DELETE CASCADE;
ALTER TABLE public.product_batch_certifications ADD CONSTRAINT product_batch_certifications_certification_id_fkey FOREIGN KEY (certification_id) REFERENCES product_certifications(id) ON DELETE RESTRICT;
ALTER TABLE public.product_batch_events ADD CONSTRAINT product_batch_events_batch_id_fkey FOREIGN KEY (batch_id) REFERENCES product_batches(id) ON DELETE CASCADE;
ALTER TABLE public.product_batches ADD CONSTRAINT product_batches_producer_id_fkey FOREIGN KEY (producer_id) REFERENCES producers(id) ON DELETE RESTRICT;
ALTER TABLE public.product_batches ADD CONSTRAINT product_batches_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT;
ALTER TABLE public.product_batches ADD CONSTRAINT product_batches_variant_id_fkey FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT;
ALTER TABLE public.product_certifications ADD CONSTRAINT product_certifications_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE;
